public void processSecureData(Path filePath) throws IOException {
    // Multiple resources: BufferedReader and BufferedWriter will be closed in reverse order
    try (BufferedReader reader = Files.newBufferedReader(filePath, StandardCharsets.UTF_8);
         BufferedWriter writer = Files.newBufferedWriter(filePath.resolveSibling("out.tmp"), StandardCharsets.UTF_8)) {

        String line;
        while ((line = reader.readLine()) != null) {
            writer.write(transform(line));
            writer.newLine();
        }
    } // Both reader.close() and writer.close() are implicitly and safely called here
}
